mapper.select:
SELECT scene_id
FROM bt_bot_scene_rel
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND bot_id = #{botId}

SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_bot_scene a
LEFT JOIN bt_bot_scene_rel r ON a.scene_id = r.scene_id AND a.tenant_id = r.tenant_id
LEFT JOIN bt_bot b ON r.bot_id = b.bot_id AND r.tenant_id = b.tenant_id
WHERE a.status_cd = '00A'
AND b.status_cd = '00A'
AND r.status_cd = '00A'
AND a.tenant_id = #{tenantId}
AND a.scene_id = #{sceneId}

  AND b.bot_id = #{botId}

SELECT a.bot_id
FROM bt_bot_scene_rel a
WHERE a.tenant_id = #{tenantId}
  AND a.scene_id = #{sceneId}

SELECT id, theme_id, theme_name
FROM bt_chat_theme
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND bot_id = #{botId}
